export type Cell = [number, number];

const MIN_LIVE_NEIGHBORS_FOR_SURVIVAL = 2;
const MAX_LIVE_NEIGHBORS_FOR_SURVIVAL = 3;
const LIVE_NEIGHBORS_FOR_REPRODUCTION = 3;

export function nextGeneration(cells: Cell[]): Cell[] {
  const living = new Set(cells.map(keyOf));
  const survivors = cells.filter((cell) => survives(cell, living));
  const born = deadNeighborsOf(cells, living).filter((cell) =>
    isBorn(cell, living),
  );
  return [...survivors, ...born];
}

function survives(cell: Cell, living: Set<string>): boolean {
  const liveNeighbors = countLiveNeighbors(cell, living);
  return (
    liveNeighbors >= MIN_LIVE_NEIGHBORS_FOR_SURVIVAL &&
    liveNeighbors <= MAX_LIVE_NEIGHBORS_FOR_SURVIVAL
  );
}

function isBorn(cell: Cell, living: Set<string>): boolean {
  return countLiveNeighbors(cell, living) === LIVE_NEIGHBORS_FOR_REPRODUCTION;
}

function deadNeighborsOf(livingCells: Cell[], living: Set<string>): Cell[] {
  const dead = new Map<string, Cell>();
  for (const cell of livingCells) {
    for (const neighbor of neighborsOf(cell)) {
      if (!living.has(keyOf(neighbor))) {
        dead.set(keyOf(neighbor), neighbor);
      }
    }
  }
  return [...dead.values()];
}

function neighborsOf([x, y]: Cell): Cell[] {
  const offsets = [-1, 0, 1];
  return offsets.flatMap((dx) =>
    offsets
      .filter((dy) => !(dx === 0 && dy === 0))
      .map((dy): Cell => [x + dx, y + dy]),
  );
}

function countLiveNeighbors(cell: Cell, living: Set<string>): number {
  return neighborsOf(cell).filter((neighbor) => living.has(keyOf(neighbor)))
    .length;
}

function keyOf([x, y]: Cell): string {
  return `${x},${y}`;
}
EOF
